std::string markdown_to_html(std::string markdown) {
    // Replace newline characters with br tags
    markdown.replace(std::regex{ "\r\n|\r|\n" }, "<br>\n");

    // Convert asterisks to emphasis tags
    markdown.replace(std::regex{ "(\\*[^*]\\*)|([^\\*][*\\*])|([*][^\\*][^*])" }, "<em>$1</em>");

    // Convert underscores to emphasis tags
    markdown.replace(std::regex{ "([^_][__][^_])|(^[_][^_][^_])|([__][^_][^_])" }, "<strong>$1</strong>");

    // Convert 1-3 dashes to strong tags
    markdown.replace(std::regex{ "([^-]{3,}|^[^-]{4,})" }, "<strong>$1</strong>");

    // Convert 1-3 asterisks to emphasis tags
    markdown.replace(std::regex{ "([^*]{3,}|^[^*]{4,})" }, "<em>$1</em>");

    // Convert headers
    markdown.replace(std::regex{ "^([ \\t]*\\#+[ \\t]+.*)$" }, "<h3>$1</h3>\n");
    markdown.replace(std::regex{ "^([ \\t]*\\##+[ \\t]+.*)$" }, "<h2>$1</h2>\n");
    markdown.replace(std::regex{ "^([ \\t]*\\###+[ \\t]+.*)$" }, "<h1>$1</h1>\n");

    return markdown;
}
