  });

  await interaction.options.create(interaction.options.InteractionOptionTypes.USER, {
    user: user.id
  });

  await interaction.options.create(interaction.options.InteractionOptionTypes.STRING, {
    name: 'reason'
  });

  interaction.options.setSubcommandInteraction('ban');
});

client.login('Your token here');

