  console.log(`Logged in as ${client.user.username} (${client.user.id})`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isInteraction(Intents.FLAGS.GIVEN)) {
    return;
  }

  if (!interaction.options) {
    return;
  }

  if (!interaction.options.commandName) {
    return;
  }

  if (interaction.options.commandName === 'ban') {
    const user = await interaction.options.getUser('user');

    if (!user) {
      return;
    }

    const reason = interaction.options.getString('reason');

    if (!reason) {
      return;
    }

    await interaction.options.create(interaction.options.InteractionOptionTypes.STRING, {
      name: 'reason'
    });

    await interaction.options.create(interaction.options.InteractionOptionTypes.USER, {
      user: user.id
    });

    await interaction.options.create(interaction.options.InteractionOptionTypes.APPLICATION_ Command, {
      name: 'ban'
    });

    await interaction.interaction.options.run(interaction.options.InteractionOptionTypes.USER, user.id, reason);

    interaction.options.reset(interaction.options.InteractionOptionTypes.USER, user.id);

    interaction.options.reset(interaction.options.InteractionOptionTypes.APPLICATION_ Command, interaction.interaction.options.commandName);
  }
});

client.login('Your token here');
