def timsort (s: Array (Array Int)):
  if s.size == 0 then
    return []
  if s.size == 1 then
    return s.head
  let minRun := 32
  let mutS := s.update_range (0, 0) (Array.unit ())
  while mutS.size > 1 do
    let mutS := doit minRun mutS
    minRun := min minRun 2
  return mutS.head

