extends KinematicBody2D

func _physics_process(delta):
    # Get the direction the character is facing
    var direction = -self.get_global_transform().basis.z.normalized()

    # Move the character in the direction it's facing
    self.set_position(self.position + direction * self.speed * delta)

    # Check if the character has collided with anything
    if self.collision_shape.check_collision_recursive(self.global_transform.origin):
        # Stop the character from moving
        self.speed = 0

func _on_controller_pressed():
    if Input.is_action_pressed("move_forward"):
        self.speed = 10
    if Input.is_action_pressed("move_backward"):
        self.speed = -10
    if Input.is_action_pressed("move_left"):
        self.speed = -10
    if Input.is_action_pressed("move_right"):
        self.speed = 10

func _input(event):
    # Use the input event to update the character's movement direction
    if Input.is_action_pressed("move_forward") or Input.is_action_pressed("move_backward"):
        direction = Input.get_action_vector("move_forward") + Input.get_action_vector("move_backward")
        direction = direction.normalized()
        self.set_global_transform(self.transform.basis.xform(direction))
    if Input.is_action_pressed("move_left") or Input.is_action_pressed("move_right"):
