Here is a C++ function that converts markdown to HTML:

```cpp
std::string markdownToHTML(const std::string& markdown) {
    std::string html;
    bool in_code = false;

    for (char c : markdown) {
        if (c == '`') {
            in_code = !in_code;
            html += in_code ? "<code>" : "</code>";
        } else if (c == '*' && !in_code) {
            html += "<em>";
        } else if (c == '**' && !in_code) {
            html += "<strong>"; 
        } else if (c == '#' && !in_code) {
            html += "<h1>";
        } else if (c == '##' && !in_code) {
            html += "<h2>";
        } else if (c == '###' && !in_code) {
            html += "<h3>";
        } else if (c == '>' && !in_code) {
            html += "<blockquote>";
        } else if (c == '\n' && !in_code) {
            html += "<br>";
        } else {
            html += c;
        }

        if (c == '*' && !in_code) html += "</em>";
        if (c == '**' && !in_code) html += "</strong>";
        if (c == '#' || c == '##' || c == '###' && !in_code) html += "</h1></h2></h3>";
        if (c == '>' && !in_code) html += "</blockquote>";
    }

    return html;
}
```

This function iterates over each character in the markdown string. It checks for markdown formatting like bold (**), italics (*), headers (###), blockquotes (>), and line breaks (\n). When it encounters markdown formatting, it opens the corresponding HTML tag. When it encounters the end of the markdown formatting, it closes the HTML tag. Otherwise, it simply appends the character to the HTML string.

