```c
#include <stdio.h>
#include <conio.h>
#include <stdlib.h>
#include <time.h>

#define UP 72
#define DOWN 80 
#define LEFT 75
#define RIGHT 77

int width = 20, height = 20;
int x, y, fruitX, fruitY, score;
int tailX[100], tailY[100]; 
int nTail;
char snakeDirection;

void setup() {
    x = width / 2;
    y = height / 2;
    fruitX = rand() % width;
    fruitY = rand() % height;
    score = 0;
}

void draw() {
    system("cls");
    for (int i = 0; i < width+2; i++) {
        printf("#");
    }
    printf("\n");

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            if (j == 0) {
                printf("#");
            }
            if (i == y && j == x) {
                printf("O");
            } else if (i == fruitY && j == fruitX) {
                printf("F");
            } else {
                int ch = ' ';
                for (int k = 0; k < nTail; k++) {
                    if (tailX[k] == j && tailY[k] == i) {
                        ch = 'o';
                    }
                }
                printf("%c", ch);
            }
        }
        printf("#\n");
    }

    for (int i = 0; i < width+2; i++) {
        printf("#");
    }
    printf("\n");
    printf("Score: %d\n", score);
}

void input() {
    if (kbhit()) {
        switch (getch()) {
            case UP: 
                snakeDirection = 'U';
                break;
            case DOWN: 
                snakeDirection = 'D';
                break;
            case LEFT: 
                snakeDirection = 'L';
                break;
            case RIGHT: 
                snakeDirection = 'R';
                break;
        }
    }
}

void logic() {
    int prevX = tailX[0];
    int prevY = tailY[0];
    int prev2X, prev2Y;
    tailX[0] = x;
    tailY[0] = y;
    for (int i = 1; i < nTail; i++) {
        prev2X = tailX[i];
        prev2Y = tailY[i];
        tailX[i] = prevX;
        tailY[i] = prevY;
        prevX = prev2X;
        prevY = prev2Y;
    }
    switch (snakeDirection) {
        case 'U':
            y--;
            break;
        case 'D':
            y++;
            break;
        case 'L':
            x--;
            break;
        case 'R':
            x++;
            break;
    }
    // if snake eats the fruit
    if (x == fruitX && y == fruitY) {
        score += 10;
        fruitX = rand() % width;
        fruitY = rand() % height;
        nTail++;
    }
}

int main() {
    setup();
    while (1) {
        draw();
        input();
        logic();
    }
}
```

This implements the snake game using characters to represent the snake, fruit and walls. It handles input using the arrow keys, keeps track of the snake's tail using an array, checks for collisions with the fruit and walls, and updates the score. To use images instead, you can load the images using a library like SDL or OpenGL and draw them onto the screen instead of printing characters.

